class PigLatinTranslator {
    public String translate(String word) {
        String[] words = word.split("\\s+");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < words.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(translateWord(words[i]));
        }
        return sb.toString();
    }

    private String translateWord(String w) {
        // Rule 1: starts with a vowel, or "xr"/"yt"
        if (w.matches("^(?i)[aeiou].*") || w.startsWith("xr") || w.startsWith("yt")) {
            return w + "ay";
        }
        // Rule 3: consonants (may be none) followed by "qu"
        if (w.matches("^(?i)[^aeiou]*qu.*")) {
            int idx = w.toLowerCase().indexOf("qu") + 2;
            return w.substring(idx) + w.substring(0, idx) + "ay";
        }
        // Rule 4: one or more consonants followed by "y"
        if (w.matches("^(?i)[^aeiou]+y.*")) {
            int idx = 1;
            while (idx < w.length() && !isVowel(w.charAt(idx))) {
                idx++;
            }
            return w.substring(idx) + w.substring(0, idx) + "ay";
        }
        // Rule 2: one or more leading consonants
        int idx = 0;
        while (idx < w.length() && !isVowel(w.charAt(idx))) {
            idx++;
        }
        return w.substring(idx) + w.substring(0, idx) + "ay";
    }

    private boolean isVowel(char c) {
        char l = Character.toLowerCase(c);
        return l == 'a' || l == 'e' || l == 'i' || l == 'o' || l == 'u';
    }
}
